            aria-invalid="false"
            aria-describedby="${describedBy}"
          >
          ${helperText ? `<p class="helper-text" id="${helperId}">${helperText}</p>` : ""}
          <p class="error-message" id="${errorId}" aria-live="polite"></p>
        </div>
      `;
    }

    function ContactForm() {
      return `
        <section class="support-card" aria-labelledby="support-title">
          <p class="eyebrow">Support request</p>
          <h1 id="support-title">Contact support</h1>
          <p class="intro">
