 <body>
   <main id="app"></main>

   <script>
     const fields = [
       {
         id: "fullName",
         label: "Full name",
         type: "text",
         autocomplete: "name",
         placeholder: "Alex Morgan",
         required: true,
         validate(value) {
           return value.trim() ? "" : "Enter your full name.";
         }
       },
       {
         id: "email",
         label: "Email address",
         type: "email",
         autocomplete: "email",
         placeholder: "alex@example.com",
         required: true,
         validate(value) {
           if (!value.trim()) {
             return "Enter your email address.";
           }

           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
             ? ""
             : "Enter a valid email address, such as alex@example.com.";
         }
       },
       {
         id: "phone",
         label: "Phone number",
         type: "tel",
         autocomplete: "tel",
         placeholder: "555-123-4567",
         helperText: "Optional. Use 10 digits, such as 555-123-4567.",
         required: false,
         validate(value) {
           if (!value.trim()) {
             return "";
           }

           const digitsOnly = value.replace(/\D/g, "");
           return digitsOnly.length === 10
             ? ""
             : "Enter a 10-digit phone number, such as 555-123-4567.";
         }
       }
     ];

     function Field({ id, label, type, autocomplete, placeholder, required, helperText }) {
       const errorId = `${id}-error`;
       const helperId = helperText ? `${id}-helper` : "";
       const describedBy = [helperId, errorId].filter(Boolean).join(" ");

       return `
         <div class="form-field">
           <label for="${id}">
             ${label}${required ? ' <span class="required" aria-hidden="true">*</span>' : ""}
           </label>
           <input
             id="${id}"
             name="${id}"
             type="${type}"
             autocomplete="${autocomplete}"
             placeholder="${placeholder}"
             ${required ? "required" : ""}
             aria-invalid="false"
             aria-describedby="${describedBy}"
           >
           ${helperText ? `<p class="helper-text" id="${helperId}">${helperText}</p>` : ""}
           <p class="error-message" id="${errorId}" aria-live="polite"></p>
         </div>
       `;
     }

     function ContactForm() {
       return `
         <section class="support-card" aria-labelledby="support-title">
           <p class="eyebrow">Support request</p>
           <h1 id="support-title">Contact support</h1>
           <p class="intro">
             Send us your contact details and our support team will get back to you.
             Fields marked with an asterisk are required.
           </p>
           <p class="success-message" id="success-message" role="status">
             Thanks. Your contact details are ready to submit.
           </p>
           <form id="support-form" novalidate>
             ${fields.map(Field).join("")}
             <button type="submit">Submit request</button>
           </form>
         </section>
       `;
     }

     function App() {
       return ContactForm();
     }

     function setError(input, message) {
       const error = document.getElementById(`${input.id}-error`);
       input.setAttribute("aria-invalid", message ? "true" : "false");
       error.textContent = message;
     }

     function validateField(input) {
       const field = fields.find((item) => item.id === input.id);
       const message = field.validate(input.value);
       setError(input, message);
       return !message;
     }

     document.getElementById("app").innerHTML = App();

     const form = document.getElementById("support-form");
     const successMessage = document.getElementById("success-message");

     form.addEventListener("input", (event) => {
       if (event.target.matches("input")) {
         validateField(event.target);
         successMessage.classList.remove("is-visible");
       }
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const inputs = Array.from(form.querySelectorAll("input"));
       const validationResults = inputs.map(validateField);
       const isValid = validationResults.every(Boolean);

       successMessage.classList.toggle("is-visible", isValid);

       if (!isValid) {
         const firstInvalid = form.querySelector('[aria-invalid="true"]');
         firstInvalid.focus();
       }
     });
   </script>
 </body>
 </html>
